    ['id' => 't3', 'slug' => 'adressierung-und-routing', 'areaId' => 'a3', 'title' => 'Adressierung, Vermittlung und Routing', 'intro' => 'IP adressiert Schnittstellen und vermittelt Pakete über Subnetze und autonome Systeme.', 'blocks' => [
        ['type' => 'definition', 'title' => 'Internet, autonome Systeme und IPv4', 'content' => 'Das Internet verbindet Netze und autonome Systeme. IPv4-Adressen gliedern sich in Netz- und Hostanteil; historische Klassen, private Bereiche und Loopback-Adressen ordnen besondere Verwendungsfälle ein. Ein Endsystem vergleicht sein eigenes Präfix mit dem Zielpräfix, um zwischen direkter Zustellung im Subnetz und Weitergabe an einen Router zu entscheiden.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s05', 'Internet, autonome Systeme, IPv4 und historische Adressklassen')]],
        ['type' => 'method', 'title' => 'Subnetz und Adressbereich bestimmen', 'content' => 'Voraussetzung sind IPv4-Adresse und Präfix beziehungsweise Maske. 1. Maske aus der Präfixlänge bilden. 2. Adresse bitweise mit der Maske UND-verknüpfen; das Ergebnis ist die Netzadresse. 3. Hostbits nur 0 ergeben die Netzadresse, Hostbits nur 1 die Broadcastadresse. 4. Die dazwischenliegenden Adressen bilden den in den Aufgaben verwendeten Hostbereich. Ergebnis sind Netz, Broadcast und Zahl der nutzbaren Hosts.', 'formula' => 'Netzadresse = IPv4-Adresse AND Subnetzmaske; Hosts = 2^h − 2', 'code' => "Beispiel: Subnetz und Adressbereich bestimmen\n\nGegeben:\nIP-Adresse: 192.168.10.75\nPräfix:     /26\n\n1. Subnetzmaske aus der Präfixlänge bilden\n\n/26 bedeutet:\nNetzbits: 26 x 1\nHostbits: 32 - 26 = 6 x 0\n\n11111111.11111111.11111111.11000000\n\nUmrechnung in Dezimal:\n11111111 = 255\n11111111 = 255\n11111111 = 255\n11000000 = 192\n\nSubnetzmaske:\n255.255.255.192\n\n2. Netzadresse berechnen (bitweises UND)\n\nIP-Adresse:   192.168.10.75\n              11000000.10101000.00001010.01001011\n\nMaske:        255.255.255.192\n              11111111.11111111.11111111.11000000\n------------------------------------------------ &\nNetzadresse:  192.168.10.64\n              11000000.10101000.00001010.01000000\n\n3. Broadcastadresse bestimmen\n\nAlle Hostbits auf 1 setzen:\nBroadcastadresse: 192.168.10.127\n\n4. Hostbereich bestimmen\n\nErste Hostadresse:  192.168.10.65\nLetzte Hostadresse: 192.168.10.126\n\n5. Anzahl der nutzbaren Hosts\n\nFormel:\n2^Hostbits - 2 = 62\n\nErgebnis:\nNetzadresse:       192.168.10.64\nBroadcastadresse:  192.168.10.127\nHostbereich:       192.168.10.65 - 192.168.10.126\nNutzbare Hosts:    62", 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s05', 'IPv4, Subnetting und Auswahl einer Subnetzmaske'), $ref('e2016', 'Aufgabe 2'), $ref('p18', 'CIDR.md: Subnetzmasken, Adressräume und AND-Verknüpfung')]],
        ['type' => 'method', 'title' => 'CIDR-Routen aggregieren', 'content' => 'Voraussetzung sind benachbarte Präfixe mit demselben Next Hop. Zuerst werden gültige Netzgrenzen geprüft, danach gemeinsame führende Bits bestimmt und daraus ein kürzeres Sammelpräfix gebildet. Abschließend wird geprüft, ob das Präfix unbeabsichtigte Zwischenbereiche umfasst. Die folgenden Unterabschnitte zeigen Regel und Beispiele innerhalb dieses Artikels.', 'sections' => [
            ['type' => 'rule', 'title' => 'Regel: Gültige Netzgrenzen prüfen', 'content' => 'Ein Präfix bestimmt die Blockgröße des Netzes. Die Netzadresse darf nur am Anfang eines solchen Blocks liegen. Der Startwert eines Netzes muss ein Vielfaches seiner Blockgröße sein.', 'formula' => 'Blockgröße = 256 - Wert des letzten Masken-Oktetts', 'code' => "Für /23 gilt:\n\nMaske:       255.255.254.0\nBlockgröße:  256 - 254 = 2\nGültige Startwerte im 3. Oktett: 0, 2, 4, 6, ..."],
            ['type' => 'method', 'title' => 'Beispiel 1: Ungültige Routen prüfen', 'content' => 'Die erste Route beginnt an einer gültigen /23-Netzgrenze. Die zweite Route beginnt bei 1 und ist damit keine gültige /23-Netzadresse. Ein /23 umfasst immer zwei aufeinanderfolgende /24-Netze; die vermeintliche zweite Route liegt bereits im ersten Netz. Eine Aggregation ist daher nicht möglich.', 'code' => "Gegeben:\n10.0.0.0/23 -> Router A\n10.0.1.0/23 -> Router A\n\nPrüfung:\n10.0.0.0/23 ist gültig.\n10.0.1.0/23 ist ungültig, weil 1 kein Vielfaches der Blockgröße 2 ist.\n\nEin /23 umfasst:\n10.0.0.0/23 = 10.0.0.0/24 + 10.0.1.0/24\n\nDamit liegt 10.0.1.0 bereits innerhalb von 10.0.0.0/23.\n\nRichtige Routingtabelle:\n10.0.0.0/23 -> Router A"],
            ['type' => 'method', 'title' => 'Beispiel 2: Gültige Aggregation', 'content' => 'Beide /23-Netze beginnen an gültigen Netzgrenzen und verwenden denselben Next Hop. Zusammen decken sie vier aufeinanderfolgende /24-Netze ab. Dafür kann das gemeinsame Präfix um zwei Bits verkürzt werden: Aus vier /24-Netzen wird ein /22-Netz.', 'formula' => '/22 = 4 x /24', 'code' => "Gegeben:\n10.0.0.0/23 -> Router A\n10.0.2.0/23 -> Router A\n\nBeide Netzadressen sind gültig, da 0 und 2 Vielfache\nder Blockgröße 2 sind.\n\n10.0.0.0/23 = 10.0.0.0/24 + 10.0.1.0/24\n10.0.2.0/23 = 10.0.2.0/24 + 10.0.3.0/24\n\nZusammen sind es vier /24-Netze.\n\nErgebnis:\n10.0.0.0/22 -> Router A"]
        ], 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s06', 'CIDR, Delegation und Routenaggregation')]],
        ['type' => 'method', 'title' => 'Longest Prefix Match', 'content' => 'Für die Zieladresse werden zunächst alle Routingeinträge gesucht, deren Präfix passt. Gibt es mehrere Treffer, gewinnt der Eintrag mit den meisten festen Präfixbits, weil er das Zielnetz am genauesten beschreibt. Erst wenn kein spezifischerer Eintrag passt, greift die Default-Route 0.0.0.0/0. Der Rechner wählt damit nicht den zuerst eingetragenen, sondern den spezifischsten passenden Weg.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s06', 'Routingtabellen und Longest Prefix Match'), $ref('e2016', 'Aufgabe 2')]],
        ['type' => 'method', 'title' => 'Link State und Dijkstra', 'content' => 'Voraussetzung ist die durch Topologieinformationen bekannte Netzstruktur mit Verbindungskosten. 1. Jeder Router verteilt seine lokalen Verbindungen. 2. Alle Router bauen daraus dieselbe Topologiesicht auf. 3. Dijkstra übernimmt schrittweise den noch nicht festgelegten Knoten mit kleinster vorläufiger Distanz. 4. Die Kosten seiner Nachbarn werden über diesen Knoten aktualisiert. Ergebnis ist ein Baum kürzester Wege und daraus die Weiterleitungstabelle.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s08', 'Control Plane, Link State und Dijkstra')]],
        ['type' => 'method', 'title' => 'Distance Vector', 'content' => 'Jeder Router startet mit den bekannten Kosten zu direkten Nachbarn. Er tauscht seine Distanztabelle mit Nachbarn aus, addiert die Kosten zum jeweiligen Nachbarn und übernimmt günstigere Wege. Wiederholter Austausch führt zu angepassten Distanz- und Next-Hop-Einträgen. Im Unterschied zu Link State kennt ein Router dabei nicht zwingend die vollständige Topologie.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s08', 'Distance Vector und Protokollvergleich')]],
        ['type' => 'comparison', 'title' => 'Routingprotokolle', 'content' => 'RIP gehört zum Distance-Vector-Umfeld; OSPF und IS-IS zu Link State. Diese Protokolle arbeiten innerhalb autonomer Systeme. BGP verbindet autonome Systeme und ist damit dem Inter-AS-Routing zugeordnet.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s08', 'Intra-/Inter-AS, RIP, OSPF, IS-IS und BGP')]],
        ['type' => 'method', 'title' => 'NAT- und NAPT-Übersetzung', 'content' => 'Beim ausgehenden Paket ersetzt das NAT-Gerät die interne Adresse; NAPT ordnet zusätzlich den internen Port einem externen Port zu und speichert diese Zuordnung. Beim Antwortpaket schlägt es die Zuordnung nach und stellt interne Adresse und Port wieder her. Die Zuordnung beeinflusst eingehende Erreichbarkeit; die Folien unterscheiden Full Cone, Restricted Cone, Port Restricted Cone und Symmetric NAT und behandeln daraus entstehende Traversal-Probleme.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s07', 'NAT-/NAPT-Tabelle, NAT-Typen und Traversal')]],
        ['type' => 'method', 'title' => 'ARP und DHCP', 'content' => 'ARP sendet für eine gesuchte IPv4-Adresse eine Anfrage im lokalen Netz; der zuständige Teilnehmer antwortet mit seiner MAC-Adresse, die anschließend für den lokalen Rahmen verwendet werden kann. DHCP liefert einem Client Konfigurationsdaten wie die IP-Konfiguration. RARP wird in den Unterlagen als verwandter historischer Mechanismus eingeordnet.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s09', 'ARP Request/Reply, RARP und DHCP')]],
        ['type' => 'method', 'title' => 'IP-Fragmentierung durchführen', 'content' => 'Voraussetzung sind Paketlänge, IP-Headerlänge und MTU des nächsten Netzes. 1. Maximale Nutzdaten pro Fragment als MTU minus Header bestimmen. 2. Für alle Nicht-Endfragmente auf ein durch acht teilbares Nutzdatenvielfaches abrunden. 3. Nutzdaten aufteilen. 4. Total Length aus jeweiliger Nutzlast plus Header bilden. 5. Fragment Offset als bisher übertragene Nutzdaten geteilt durch acht eintragen. Der Offset zählt damit 8-Byte-Einheiten, nicht einzelne Bytes. More Fragments wird außer beim letzten Fragment gesetzt. Die Wiederzusammensetzung erfolgt am Ziel.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s09', 'IPv4-Header, MTU und Fragmentierung'), $ref('e2016', 'Aufgabe 2'), $ref('p18', 'MTU.md und MTU(Programm).md: MTU, Fragmentierung und Offset')]],
        ['type' => 'comparison', 'title' => 'ARP-Schichtzuordnung', 'content' => 'Die Unterlagen dokumentieren drei Perspektiven: Schicht 2 nach üblicher Literaturzuordnung, Schicht 3 aus Sicht der Betriebssystemerzeugung in der Internetarchitektur und Schicht 2.5 als Zwischenposition. Eine absolute Einzelzuordnung wäre daher irreführend.', 'items' => ['Schicht 2: Zuordnung in der Literatur', 'Schicht 3: Erzeugung durch die Internet-Schicht', 'Schicht 2.5: vermittelnde Zwischenposition'], 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s09', 'ARP und Schichtzuordnung')]],
    ], 'examNotes' => 'CIDR, Routingtabellen und Fragmentierung gehören zu den häufigsten Rechen- und Begründungsaufgaben.', 'relatedTopicIds' => ['t1', 't4'], 'clarityStatus' => 'mehrdeutig'],

    ['id' => 't4', 'slug' => 'zuverlaessigkeit-und-tcp', 'areaId' => 'a4', 'title' => 'Zuverlässigkeit und TCP', 'intro' => 'Zuverlässiger Transport kombiniert Rückmeldungen, Sequenznummern, Timer und Fenstersteuerung.', 'blocks' => [
        ['type' => 'method', 'title' => 'Stop-and-Wait und ARQ auswerten', 'content' => 'Der Sender versieht Daten mit einer Sequenznummer, sendet genau eine Einheit und startet einen Timer. Bei passendem ACK fährt er mit der nächsten Sequenznummer fort. Gehen Daten oder ACK verloren, löst der Timer eine Wiederholung aus. Trifft die Wiederholung nach einem verlorenen ACK ein, erkennt der Empfänger das Duplikat an der Sequenznummer, verwirft die Nutzdaten und bestätigt erneut. Für die Auslastung zuerst die Sendedauer L/R bestimmen und anschließend durch Sendedauer plus RTT teilen. Ein kleiner Nutzungsgrad zeigt, dass die Leitung während des Wartens ungenutzt bleibt; Pipelining kann mehrere Einheiten gleichzeitig unterwegs halten.', 'formula' => 'Nutzungsgrad ρ = (L/R) / (L/R + RTT)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s10', 'Send and Wait, verlorene Daten, verlorenes ACK und Sequenznummern'), $ref('s10', 'Nutzungsgrad und Übergang zum Pipelining')]],
        ['type' => 'comparison', 'title' => 'Go-Back-N, Selective Repeat und Selective Reject', 'content' => 'Go-Back-N akzeptiert am Empfänger nur die erwartete Reihenfolge und wiederholt nach Timeout den fehlenden sowie alle später gesendeten Rahmen. Selective Repeat puffert korrekt eingetroffene spätere Rahmen und wiederholt gezielt fehlende. Selective Reject fordert einen bestimmten fehlenden Rahmen gezielt an. Kumulative ACKs bestätigen einen zusammenhängenden Präfix; Duplicate ACKs zeigen wiederholt dieselbe Lücke.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s11', 'GBN, Selective Repeat/Reject, Pufferung und ACK-Verhalten'), $ref('p18', 'TCP_Kommunikation_Go_Back_N.md und TCP_Kommunikation_Selective_Repeat.md')]],
        ['type' => 'formula', 'title' => 'Fenster, Durchsatz und Bandwidth-Delay-Produkt', 'content' => 'Ein Fenster w begrenzt die Datenmenge, die ohne neue Bestätigung gleichzeitig ausstehen darf. Pro RTT kann höchstens diese Fenstermenge übertragen werden; der erreichbare Durchsatz hängt deshalb von Fenstergröße und Round-Trip-Zeit ab. Für volle Auslastung muss das Fenster mindestens so viele Bits aufnehmen, wie während einer RTT übertragen werden können. Bei Rechnungen Länge, Datenrate, Zeit und Bit beziehungsweise Byte in konsistenten Einheiten einsetzen.', 'formula' => 'Durchsatz ≤ w / RTT; w ≥ Bandbreite · RTT', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s11', 'Durchsatz und Bandwidth-Delay-Produkt'), $ref('e2016', 'Aufgabe 3'), $ref('p18', 'Sliding_Window.md: Fenstergröße und Durchsatz')]],
        ['type' => 'method', 'title' => 'TCP-Fluss- und Staukontrolle', 'content' => 'Der Empfänger meldet im Receiver Window freien Puffer; der Sender hält seine ausstehenden Daten darunter. Zusätzlich begrenzt das Congestion Window die Netzbelastung. Slow Start vergrößert das Staufenster anfangs stark, Congestion Avoidance anschließend vorsichtiger. Mehrere Duplicate ACKs können eine vermutete Lücke per Fast Retransmit vor dem Timeout erneut senden; Fast Recovery passt danach das Fenster an.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'Receiver Window, Slow Start, Congestion Avoidance, Fast Retransmit und Recovery')]],
        ['type' => 'method', 'title' => 'RTT und Timeout nachführen', 'content' => 'TCP misst die Zeit zwischen Senden und passender Bestätigung. Die Unterlagen bilden aus Messungen eine geglättete RTT-Schätzung und berücksichtigen die Abweichung für den Timeout. Der Timeout muss auf wechselnde Laufzeiten reagieren: zu klein erzeugt unnötige Wiederholungen, zu groß verzögert die Fehlerreaktion.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'RTT-Schätzung und Retransmission Timeout')]],
        ['type' => 'method', 'title' => 'TCP-Verbindung auf- und abbauen', 'content' => 'Beim Aufbau synchronisieren Client und Server ihre Sequenzräume mit SYN, SYN+ACK und ACK. Danach ist die Verbindung in beiden Richtungen nutzbar. Beim regulären Abbau werden die beiden Richtungen mit FIN und ACK getrennt geschlossen, weshalb der Ablauf vier Segmente umfassen kann. Die Zustände verhindern, dass alte Segmente unmittelbar einer neuen Verbindung zugerechnet werden.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'Drei-Wege-Handshake, Verbindungsabbau und Zustände')]],
        ['type' => 'definition', 'title' => 'TCP-Header und Zusatzmechanismen', 'content' => 'Ports identifizieren Anwendungen, Sequenz- und ACK-Nummer ordnen den Byte-Strom, Flags steuern Aufbau und Abbau, das Fenster meldet Empfangskapazität. Delayed ACK wartet kurz auf eine gemeinsame Bestätigung, Piggybacking verbindet ACK und Rückdaten, Nagle bündelt kleine Sendungen; Push und Urgent Pointer markieren besondere Behandlung im in den Unterlagen dargestellten Modell.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'TCP-Header, Delayed ACK, Piggybacking, Nagle, Push und Urgent Pointer')]],
    ], 'examNotes' => 'Fehlerabläufe, Fenstergrößen und TCP-Durchsatz werden wiederholt geprüft.', 'relatedTopicIds' => ['t3', 't5', 't7'], 'clarityStatus' => 'unklar'],

    ['id' => 't5', 'slug' => 'udp-dns-und-anwendungsprotokolle', 'areaId' => 'a5', 'title' => 'UDP, DNS und Anwendungsprotokolle', 'intro' => 'Anwendungsprotokolle nutzen unterschiedliche Transport- und Darstellungsmechanismen.', 'blocks' => [
        ['type' => 'definition', 'title' => 'UDP-Header und Checksumme', 'content' => 'UDP ist verbindungslos. Sein Header enthält Quell- und Zielport, Länge und Checksumme. Zur Prüfsumme werden die in den Unterlagen vorgesehenen Wörter einschließlich zusätzlicher IP-bezogener Angaben einbezogen; der Empfänger berechnet erneut und erkennt eine Abweichung, ohne dass UDP selbst Wiederholung oder Reihenfolge garantiert.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s13', 'UDP-Header und Checksumme')]],
        ['type' => 'method', 'title' => 'UDP-DNS-Mockup praktisch umsetzen', 'content' => 'Der Mockup-Server bindet einen DatagramSocket an einen Port, empfängt DatagramPackets und liest daraus DNS-Namen, Client-Adresse und Client-Port. Eine HashMap liefert die passende IP-Adresse; unbekannte Namen erhalten die Antwort unbekannt. Der Server baut daraus ein neues DatagramPacket und sendet es zurück. Der Client sendet jedes eingegebene Namenspaket und empfängt die Antwort unabhängig von einer TCP-Verbindung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('p14', '01_server.txt, 02_client.txt und 03_client-thread.txt')]],
        ['type' => 'method', 'title' => 'Medien digitalisieren und Bitrate bestimmen', 'content' => 'Ein analoges Signal wird abgetastet, jeder Messwert quantisiert und anschließend binär kodiert. Die Abtastrate muss laut Nyquist mindestens doppelt so groß wie die höchste Signalfrequenz sein. Abtastrate, Bits je Wert und Kanalzahl ergeben die unkomprimierte Bitrate. Ergebnis ist ein digitaler Datenstrom für Speicherung oder Übertragung.', 'formula' => 'Abtastfrequenz ≥ 2 · maximale Signalfrequenz; Bitrate = Abtastrate · Bits je Wert · Kanäle', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s13', 'Abtastung, Quantisierung, Kodierung und Bitrate')]],
        ['type' => 'method', 'title' => 'Streaming und Wiedergabepuffer', 'content' => 'Pakete treffen wegen Laufzeitschwankungen nicht gleichmäßig ein. Ein Playback-Puffer sammelt zunächst Daten und startet die Wiedergabe verzögert. Danach entnimmt die Anwendung mit gleichmäßiger Rate. Ein größerer Puffer toleriert mehr Jitter, erhöht aber die Verzögerung. RTP transportiert Mediendaten, RTCP liefert Kontrollinformationen und RTSP steuert Sitzungen; HLS und DASH segmentieren adaptive Übertragung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s13', 'Streaming, Jitter, Playback-Puffer und Medienprotokolle')]],
        ['type' => 'method', 'title' => 'UDP-Videostreaming mit Frames', 'content' => 'Das Praktikum nutzt UDP für einzelne MJPEG-Bilder, weil bei Medienübertragung oft geringe Verzögerung wichtiger ist als die Wiederholung jedes verlorenen Pakets. PLAY_STREAM und PAUSE_STREAM steuern serverseitig einen Timer; dessen ActionListener sendet regelmäßig den nächsten Frame. Der Client empfängt die Datagramme in einem eigenen Thread und zeigt die Bytefolge als Image an. Die vereinfachte Aufgabe verzichtet auf einen Clientpuffer; in realen Systemen puffert der Client und gibt mit der Framerate aus.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('p15', 'videostream.txt: PLAY_STREAM, PAUSE_STREAM und Frame-Versand')]],
        ['type' => 'method', 'title' => 'DNS-Namensraum und Auflösung', 'content' => 'Der hierarchische DNS-Namensraum besteht aus Labels; ein vollständiger Name ist ein FQDN. Eine Domäne bezeichnet einen Teilbaum, eine Zone den administrativ von einem Nameserver verantworteten Teil. Resource Records speichern Zuordnungen und Verweise, und Unterdomänen können an andere Nameserver delegiert werden. Bei rekursiver Auflösung übernimmt der befragte Nameserver die weiteren Anfragen und liefert das Ergebnis. Bei iterativer Auflösung erhält der Anfragende Verweise und folgt ihnen selbst von der Hierarchie zur zuständigen Zone. Caching spart Anfragen, kann aber veraltete oder manipulierte Einträge weitertragen.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s14', 'Labels, FQDN, Domänen, Zonen, Delegation und Records'), $ref('s14', 'Rekursive/iterative Auflösung, Records, Caching und Angriffe')]],
        ['type' => 'method', 'title' => 'TLS im Client-Server-Praktikum', 'content' => 'Ein TCP-Echoserver wird durch SSLServerSocket und der Client durch SSLSocket abgesichert. Vor dem Aufbau der SSL-Factories setzt die JVM die Pfade zu KeyStore und TrustStore. Im TLS-Handshake werden unter anderem Zertifikat und Sitzungsschlüssel ausgehandelt; danach schützt symmetrische Verschlüsselung Vertraulichkeit und Integrität der Nutzdaten. Der TrustStore enthält das vertrauenswürdige Zertifikat ohne den privaten Schlüssel des Servers.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('p12', '01_einfuehrung.md, 02_certificate_store.md und 03_tls-serverclient.md')]],
        ['type' => 'comparison', 'title' => 'Transportverschlüsselung und Ende-zu-Ende-Verschlüsselung', 'content' => 'Bei Transportverschlüsselung kann der Server die Nachricht nach der Entschlüsselung lesen, weil er selbst Kommunikationspartner oder Vermittler ist. Bei Ende-zu-Ende-Verschlüsselung verschlüsselt Client 1 mit dem öffentlichen Schlüssel von Client 2; nur dessen privater Schlüssel entschlüsselt den Inhalt. Der Server routet die Nachricht anhand von Metadaten, kennt aber den verschlüsselten Inhalt nicht. TLS kann zusätzlich den Transportweg zwischen Client und Server schützen.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('p17', '01_einfuehrung.md, 02_aufgabe.txt und 04_transportwegverschluesselung.txt'), $ref('p12', 'TLS-Echoserver und Zertifikatsspeicher')]],
        ['type' => 'comparison', 'title' => 'Aktives und passives FTP', 'content' => 'FTP trennt Steuer- und Datenverbindung. Beim aktiven FTP baut der Server die Datenverbindung zum Client auf; beim passiven FTP teilt der Server einen erreichbaren Port mit und der Client baut auch die Datenverbindung auf. Die Rollen beim Datenverbindungsaufbau sind der entscheidende Unterschied.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s15', 'FTP: Steuerverbindung, aktiver und passiver Modus')]],
        ['type' => 'comparison', 'title' => 'E-Mail-Protokolle und MIME', 'content' => 'SMTP transportiert Nachrichten zum Server und zwischen Servern. POP3 und IMAP dienen dem Abruf; IMAP unterstützt die serverseitige Verwaltung stärker. MIME erweitert das Nachrichtenformat um unterschiedliche Inhaltstypen und Anhänge.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s15', 'SMTP, POP3, IMAP und MIME')]],
    ], 'examNotes' => 'TLS und Serialisierung erscheinen im Gedächtnisprotokoll 2018 nur als Relevanzhinweis.', 'relatedTopicIds' => ['t2', 't4'], 'clarityStatus' => 'unklar'],

    ['id' => 't6', 'slug' => 'lan-und-ethernet', 'areaId' => 'a6', 'title' => 'LAN, Medienzugriff und Ethernet', 'intro' => 'Die Sicherungsschicht rahmt Daten und regelt den gemeinsamen Zugriff auf ein Medium.', 'blocks' => [
        ['type' => 'definition', 'title' => 'Framing, Medien und Netzkomponenten', 'content' => 'LLC und MAC teilen Aufgaben der Sicherungsschicht. Bus, Ring und Stern beschreiben Topologien. Repeater regeneriert Signale, ein Hub verteilt sie an alle Ports. Bridge und Switch filtern Rahmen anhand gelernter MAC-Adressen; ein Router vermittelt Pakete zwischen Netzen. Kupfer und Glasfaser unterscheiden sich in Übertragungsmedium und den in den Folien verglichenen Reichweiten- und Störeigenschaften.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s16', 'Sicherungsschicht, Topologien, Komponenten und Übertragungsmedien')]],
        ['type' => 'method', 'title' => 'Switch-Learning und Broadcast', 'content' => 'Bei jedem eingehenden Rahmen merkt sich der Switch die Quell-MAC-Adresse zusammen mit dem Eingangsport. Ist die Zieladresse bekannt, leitet er nur zum zugehörigen Port weiter; ist sie unbekannt oder ein Broadcast, verteilt er den Rahmen an die übrigen Ports. Gelernte Einträge ermöglichen anschließend gezielte Weiterleitung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s16', 'Bridge, Switch-Learning und Broadcast-Verhalten')]],
        ['type' => 'method', 'title' => 'CSMA/CD und Binary Exponential Backoff', 'content' => 'Eine Station hört das Medium und sendet bei Freiheit. Während des Sendens überwacht sie Kollisionen. Nach einer Kollision bricht sie ab; Binary Exponential Backoff wählt zufällig einen Wartewert aus einem mit den Versuchen wachsenden Bereich. Danach prüft die Station erneut. Das Ergebnis ist eine dezentrale Wiederholungsregel, deren Wartebereich bei anhaltender Last wächst.', 'formula' => 'Sendedauer ≥ 2 · maximale Signallaufzeit', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'CSMA/CD und Binary Exponential Backoff')]],
        ['type' => 'definition', 'title' => 'Ethernet-Rahmen und Mindestrahmen', 'content' => 'Der Ethernet-Rahmen enthält Präambel/Startbegrenzung, Ziel- und Quelladresse, Längen-/Typfeld, Nutzdaten mit gegebenenfalls Padding und FCS. Die Mindestlänge stellt sicher, dass der Sender während der maximalen Round-Trip-Laufzeit noch sendet und eine Kollision erkennen kann. Für das belegte 10-Mbit/s-Beispiel ergeben 51,2 µs daher 512 Bit beziehungsweise 64 Byte. Fast und Gigabit Ethernet erhöhen die Rate; bei gleicher Mindestlänge verkürzt sich dadurch die zulässige Netzausdehnung.', 'formula' => '10 Mbit/s · 51,2 µs = 512 Bit = 64 Byte', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'Ethernet-Rahmen, Fast Ethernet und Gigabit Ethernet'), $ref('s17', 'Ethernet-Mindestrahmen'), $ref('e2016', 'Aufgabe 5')]],
        ['type' => 'comparison', 'title' => 'Kanalzuteilung und ALOHA', 'content' => 'TDMA und FDMA teilen Zeit beziehungsweise Frequenz fest auf. ALOHA lässt Stationen konkurrierend senden und reagiert auf Konflikte; CSMA hört zuvor das Medium. Die Verfahren unterscheiden feste Zuteilung von dynamischem Wettbewerb und damit Auslastung und Kollisionsrisiko.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'TDMA, FDMA, ALOHA und CSMA-Taxonomie')]],
        ['type' => 'method', 'title' => 'Token Ring', 'content' => 'Ein Token umläuft den Ring. Nur die Station mit Token darf senden und gibt es anschließend weiter. Dadurch werden Kollisionen vermieden und der Zugriff geordnet. Gegenüber konkurrierendem CSMA entsteht vorhersagbarerer und fairer Zugriff, aber der Token und die Ringorganisation erzeugen zusätzlichen Ablaufaufwand.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'Token Ring und Vergleich zum konkurrierenden Zugriff')]],
    ], 'examNotes' => 'Ethernet-Mindestlänge, Fast Ethernet und Bridge-Verhalten sind wiederkehrende Prüfungsthemen.', 'relatedTopicIds' => ['t7', 't8'], 'clarityStatus' => 'mehrdeutig'],

    ['id' => 't7', 'slug' => 'hamming-und-crc', 'areaId' => 'a7', 'title' => 'Hamming-Abstand und CRC', 'intro' => 'Redundanz ermöglicht, Übertragungsfehler zu erkennen oder zu korrigieren.', 'blocks' => [
        ['type' => 'formula', 'title' => 'Hamming-Abstand', 'content' => 'Der Hamming-Abstand zählt verschiedene Bitpositionen. Um e Bitfehler sicher zu erkennen, ist Mindestabstand e+1 nötig; zur Korrektur e Fehler Mindestabstand 2e+1.', 'formula' => 'd_min ≥ e + 1 (Erkennung); d_min ≥ 2e + 1 (Korrektur)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s18', 'Hamming-Abstand und Fehlerfähigkeit'), $ref('p18', 'Bitfolgen.md: Hamming-Distanz')]],
        ['type' => 'comparison', 'title' => 'Parität, FEC und ARQ', 'content' => 'Ein Paritätsbit ergänzt eine Bitfolge um Redundanz, sodass bestimmte Fehler erkannt werden können; es korrigiert die fehlerhafte Stelle aber nicht zuverlässig. Forward Error Correction fügt genügend Prüfinformationen hinzu, damit der Empfänger Fehler ohne Rückfrage erkennen und korrigieren kann. ARQ nutzt dagegen eine Rückmeldung: Erkennt der Empfänger einen Fehler oder fehlt eine Bestätigung, fordert er eine erneute Übertragung an. Parität, FEC und ARQ unterscheiden sich damit durch Prüfaufwand, Korrekturmöglichkeit und benötigten Rückkanal.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s18', 'Parität, FEC und ARQ')]],
        ['type' => 'method', 'title' => 'CRC-Verfahren schriftlich anwenden', 'content' => 'Die Daten D werden um r Nullbits erweitert und modulo 2 durch das Generatorpolynom G dividiert. Dazu den Generator an der führenden 1 des aktuellen Dividendenrests ausrichten und die Bits per XOR verknüpfen; bis zum Ende wiederholen. Der r Bit lange Rest R wird an die ursprünglichen Daten gehängt. Der Empfänger dividiert das vollständige Codewort erneut; Rest 0 bedeutet, dass die CRC-Prüfung besteht.', 'formula' => 'R = Rest von (D · 2^r) / G in Modulo-2-Arithmetik', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s18', 'CRC und Polynomcodes'), $ref('s18', 'Durchgerechnetes CRC-Beispiel und Lösung'), $ref('e2016', 'Aufgabe 5'), $ref('e2016', 'Aufgabe 5d'), $ref('p18', 'CRC.md: Generatorpolynom und XOR-Rechnung'), $ref('p18', 'CRC.md: ausführliche CRC-Aufgaben')]],
    ], 'examNotes' => 'CRC-Rechnungen und Hamming-Abstände sind prüfungsrelevant.', 'relatedTopicIds' => ['t4', 't6'], 'clarityStatus' => 'unklar'],

    ['id' => 't8', 'slug' => 'leitungscodes-modulation-wlan', 'areaId' => 'a8', 'title' => 'Leitungscodes, Modulation und WLAN', 'intro' => 'Bits werden als Leitungssignale oder modulierte Träger übertragen; Funknetze benötigen besondere Zugriffsregeln.', 'blocks' => [
        ['type' => 'comparison', 'title' => 'Basisband, Breitband und Anforderungen', 'content' => 'Basisband überträgt das codierte Signal direkt im verfügbaren Band; Breitband legt Information auf Trägerbereiche. Leitungscodes werden in den Unterlagen unter anderem nach Gleichanteil, Taktrückgewinnung, Bandbreitenbedarf und eindeutiger Dekodierbarkeit beurteilt.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'Basis-/Breitband und Anforderungen an Leitungscodes')]],
        ['type' => 'method', 'title' => 'Leitungscodes zeichnen und vergleichen', 'content' => 'Zuerst Bitgrenzen und einen konsistenten Startpegel markieren. Für jedes Bit die jeweilige Regel anwenden: NRZ arbeitet mit Pegeln, NRZI mit Übergang oder Nichtübergang, RZ kehrt innerhalb des Bits zurück, Manchester besitzt einen Übergang in der Bitmitte und Differential Manchester wertet Übergänge relativ aus. Danach Signalwechsel, Gleichanteil und Taktrückgewinnung vergleichen.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'NRZ, NRZI, RZ, Manchester und Differential Manchester'), $ref('p18', 'Bitfolgen.md: Manchester, differentielles NRZ und NRZ')]],
        ['type' => 'method', 'title' => 'Blockcodes anwenden', 'content' => 'Bei 4B/5B wird jede Vier-Bit-Gruppe über die in den Unterlagen gegebene Tabelle auf fünf Codebits abgebildet; daraus folgt 80 Prozent Nutzbitanteil. 8B/10B bildet acht Datenbits auf zehn Codebits ab und verfolgt zusätzliche Signaleigenschaften. Für konkrete Kodierungen ist die jeweilige Quelltabelle maßgeblich.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', '4B/5B- und 8B/10B-Codierungstabellen')]],
        ['type' => 'comparison', 'title' => 'Modulationsverfahren auswählen', 'content' => 'ASK ordnet Symbolen Amplituden, FSK Frequenzen und PSK Phasen zu. BPSK verwendet zwei, QPSK vier Phasenlagen und trägt laut lesbarem Spezialfall zwei Bit je Symbol. QAM kombiniert Amplitude und Phase für mehr Signalpunkte. Zur Auswahl werden benötigte Symbolzahl, Robustheit und die in den Unterlagen gezeigten Signalräume verglichen.', 'formula' => 's(t) = A · sin(2πft + φ)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'ASK, FSK, BPSK, QPSK und QAM')]],
        ['type' => 'formula', 'title' => 'Kanaleigenschaften', 'content' => 'Mit wachsender Entfernung d nimmt die freie Empfangsleistung ab; in der vereinfachten Darstellung proportional zu 1/d^a. Die theoretische Kanalkapazität steigt mit der Bandbreite B und mit dem Signal-Rausch-Verhältnis SNR, erreicht aber bei gegebenen Kanaleigenschaften eine Grenze. Eine größere Bandbreite oder ein besseres SNR kann die Kapazität erhöhen, ersetzt aber keine geeignete Modulation und Codierung.', 'formula' => 'C = B · log₂(1 + SNR)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'Ausbreitung, SNR und Shannon')]],
        ['type' => 'method', 'title' => 'CSMA/CA im WLAN', 'content' => 'WLAN arbeitet in Infrastruktur- oder Ad-hoc-Netzen und nutzt Kanäle sowie MIMO. Wegen Hidden und Exposed Stations wird Kollisionserkennung durch Vermeidung ersetzt: Nach freiem Medium und IFS zählt die Station einen zufälligen Backoff herunter, sendet und erwartet ein ACK. Optional reservieren RTS und CTS das Medium vor den Nutzdaten.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'WLAN, CSMA/CA, ACK und RTS/CTS')]],
    ], 'examNotes' => 'Leitungscodes, QAM sowie der Unterschied zwischen CSMA/CD und CSMA/CA werden häufig geprüft.', 'relatedTopicIds' => ['t6', 't7'], 'clarityStatus' => 'unklar'],
];